import logging
from .models import ServicePoolDetails, ProxyServiceStatus


class UeProxyServicePool:
    """
    UeProxyPool singleton class - container for ueproxy services.
    """
    services = {}  # ue_type --> ServicePoolDetails

    def __init__(self):
        """Initiating ueproxy service pool."""
        self.logger = logging.getLogger('al.ueproxy_service_pool')

    async def create_service(self, ue_type, info=None, process=None, console=None):
        """
        Create ueproxy service.

        :param str ue_type: ue type
        :param int port: ueproxy port
        :param str info: ueproxy info
        :param str process: ueproxy process
        :param str console: ueproxy console
        """
        self.logger.info(f"Creating service pool object for {ue_type}")
        if ue_type not in self.services:
            self.services[ue_type] = ServicePoolDetails(status=ProxyServiceStatus.STARTING, info=info, process=process,
                                                        console=console, tests_in_progress=1)
        else:
            logging.warning(f"UeProxy service of {ue_type} type already exists!\n"
                            f"running services: {self.services}")

    def activate_service(self, ue_type, process, details, console_log):
        """
        Mark ueproxy active service.

        :param str port: port
        :param str process: process
        :param str details: details
        :param str console_log: console log
        """
        self.logger.info("Activating service pool object")
        if ue_type in self.services:
            self.services[ue_type].process = process
            self.services[ue_type].info = details
            self.services[ue_type].console = console_log
            self.services[ue_type].status = ProxyServiceStatus.ACTIVE

    def deactivate_service(self, ue_type):
        """
        Mark ueproxy inactive service.

        :param str ue_type: ue type
        """
        self.logger.info("Deactivating service pool object")
        if ue_type in self.services:
            self.services[ue_type].tests_in_progress -= 1
            if not self.services[ue_type].tests_in_progress:
                self.services[ue_type].status = ProxyServiceStatus.INACTIVE

    def get_service(self, ue_type):
        """
        Get active ueproxy service.

        :param str ue_type: ue type
        :return: ueproxy service if exist, otherwise {}
        """
        self.logger.info("Get service pool object details")
        return self.services.get(ue_type, {})

    def delete_service(self, ue_type):
        """
        Delete ueproxy service.

        :param str ue_type: ue type
        """
        self.logger.info("Deleting service pool object")
        del self.services[ue_type]

    def add_test_in_progress(self, ue_type):
        """
        Increase test in progress counter

        :param str ue_type: ue type
        """
        self.logger.info("Schedule test in progress")
        if ue_type in self.services:
            self.services[ue_type].tests_in_progress += 1

    def get_service_port(self, ue_type):
        """
        Return port on which ueproxy has been deployed

        :param str ue_type: ue type
        """
        self.logger.info("Getting service port")
        if self.services.get(ue_type):
            return int(self.services[ue_type].info.service.url.split(':')[-1])
        self.logger.warning(f"Ueproxy service {ue_type} type not found!")
        return None
